-- R6J verify exact risky-action permissions.
SELECT BUTTON_ID,MENU_ID,HTTP_METHOD,API_PATTERN FROM adm_button WHERE BUTTON_ID IN ('FEATURE_FLAG_OVERRIDE_REQUEST','FEATURE_FLAG_OVERRIDE_APPROVE','FEATURE_FLAG_OVERRIDE_REVOKE','FEATURE_FLAG_KILL_SWITCH','OPENAPI_REFRESH','RESILIENCE_POLICY_REQUEST','RESILIENCE_POLICY_APPROVE','RESILIENCE_POLICY_REJECT') ORDER BY BUTTON_ID;
SELECT API_PERMISSION_ID,BUTTON_ID,USE_YN FROM adm_api_permission WHERE BUTTON_ID IN ('FEATURE_FLAG_OVERRIDE_REQUEST','FEATURE_FLAG_OVERRIDE_APPROVE','FEATURE_FLAG_OVERRIDE_REVOKE','FEATURE_FLAG_KILL_SWITCH','OPENAPI_REFRESH','RESILIENCE_POLICY_REQUEST','RESILIENCE_POLICY_APPROVE','RESILIENCE_POLICY_REJECT') ORDER BY API_PERMISSION_ID;
